const texto = $('XML6').first().json.nfeProc.NFe.infNFe.infAdic.infCpl; // Substitua "texto" pelo campo onde está o texto original
const regex = /STD NUMERO:\s(\d+).*?CARGA:\s(\d+).*?BOX:\s(\d+).*?MICRO ZONA:\s([A-Z\s]+\d+).*?de\s(\d{2}-\d{2}-\d{4})/;
const match = texto.match(regex);

if (match) {
  return {
    data: {
      numero: match[1],
      numeroCarga: match[2],
      box: match[3],
      microZona: match[4],
      dataEntrega: match[5]
    }
  };
} else {
  return { data: null };
}

